using Astrea.BattleActions;
using LittleLeo;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "RealityDisruptionEffect", menuName = "Data/Battle/Effects/Enemy/RealityDisruption Effect")]
public class RealityDisruptionEffect : Effect
{
	[Header("Unstable Cloud Effect")]
	[SerializeField]
	private RandomAllTargetsLightningAction randomCorruptedLightningAction;

	[SerializeField]
	private float delayToStartCorruptedLightningAction;

	[SerializeField]
	private int realityDisruptionIncreaseAmount;

	[Header("Description")]
	[SerializeField]
	private BattleAction meteorRainAction;

	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		string arg = amount.ToString();
		if (amount == EffectsValues.NO_VALUE)
		{
			arg = base.localizationManager.GetLocalizedX();
		}
		return Smart.Format(GetLocalizedDescription(), base.localizationManager.GetLocalizedAtTheStartOfEnemiesTurn(), arg, base.localizationManager.GetLocalizedThenIncreaseEffect(this, 1)) + AppendedDescription();
	}

	public override int ActivateEffect(int amount, GameObject effectOwner)
	{
		SpriteControl spriteControl = effectOwner.GetComponent<SpriteControl>();
		spriteControl.PlayAnimation(AnimationType.SkillIdle, AnimationChangeType.StayInTheNewAnimationLooping);
		GameObject vfx = null;
		InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, delayToStartCorruptedLightningAction, delegate
		{
			if (IsVFXEnabled())
			{
				vfx = GetVFX(GetVFXOwnerPosition(effectOwner));
				vfx.GetComponent<ParticleEmissionController>().SetActive(value: true);
			}
		});
		randomCorruptedLightningAction.CastAmountWithActionAndDelayToStart(amount, effectOwner, delayToStartCorruptedLightningAction, null, delegate
		{
			if (IsVFXEnabled() && vfx != null)
			{
				vfx.GetComponent<ParticleEmissionController>().SetActive(value: false);
				ReferenceSingleton<PoolHandler>.Instance.StoreObject(vfx, 3f);
			}
			spriteControl.PlayAnimationForced(AnimationType.Idle, AnimationChangeType.StayInTheNewAnimationLooping);
			effectOwner.GetComponent<UnitEffects>().AddEffect(this, realityDisruptionIncreaseAmount);
		});
		return amount;
	}
}
